package manifest

import (
	"bytes"
	"fmt"
	"go/format"
	"path"
	"slices"
	"strconv"
	"strings"

	"golang.org/x/mod/semver"
)

// defaultTelemetry is the telemetry factory OCB uses when a manifest names
// none.
const defaultTelemetry = "go.opentelemetry.io/collector/service/telemetry/otelconftelemetry"

// RegistryOptions steers registry generation.
type RegistryOptions struct {
	// Package is the Go package name of the generated file.
	Package string
	// Source names the manifest in the generated header.
	Source string
	// Overrides replaces the factory of a component module, by module
	// path, with a Go expression defined elsewhere in the package. The
	// module's package is then not imported by the generated file.
	Overrides map[string]string
}

// RegistryOverrides are the upstream factories internal/debugger/registry adapts, by
// module path, with the expression that replaces each.
var RegistryOverrides = map[string]string{
	// Validates without reading the host (internal/debugger/registry/filestorage.go).
	"github.com/open-telemetry/opentelemetry-collector-contrib/extension/storage/filestorage": "fileStorage()",
}

// kindPackages are the Collector packages holding each kind's Factory type,
// in the order Factories fills them.
var kindPackages = []struct {
	kind  Kind
	field string
	pkg   string
}{
	{Extensions, "Extensions", "go.opentelemetry.io/collector/extension"},
	{Receivers, "Receivers", "go.opentelemetry.io/collector/receiver"},
	{Processors, "Processors", "go.opentelemetry.io/collector/processor"},
	{Exporters, "Exporters", "go.opentelemetry.io/collector/exporter"},
	{Connectors, "Connectors", "go.opentelemetry.io/collector/connector"},
}

// GenerateRegistry writes the Go source of a registry for the manifest: the
// unmodified upstream factories (Factories) and each component package's
// type names (componentTypes, which feature gate owners resolve through).
// GenerateRelease writes the release line and modules.
func GenerateRegistry(m *Manifest, opts RegistryOptions) ([]byte, error) {
	if opts.Package == "" {
		return nil, fmt.Errorf("manifest: registry package name is required")
	}
	if m.Dist.OtelcolVersion == "" {
		return nil, fmt.Errorf("manifest: dist.otelcol_version is required")
	}
	used := map[string]bool{
		"otelcol": true, "receiver": true, "processor": true, "exporter": true,
		"connector": true, "extension": true, "factories": true, "err": true,
		"Factories": true, "Modules": true, "CollectorVersion": true,
		"componentTypes": true, "typeNames": true, "component": true, "modulesOf": true,
	}
	imports := map[string]string{} // import path -> name
	name := func(importPath, want string) string {
		if n, ok := imports[importPath]; ok {
			return n
		}
		n := want
		for i := 2; used[n]; i++ {
			n = want + strconv.Itoa(i)
		}
		used[n] = true
		imports[importPath] = n
		return n
	}

	telemetry := Module{Import: defaultTelemetry}
	if m.Telemetry != nil {
		telemetry = *m.Telemetry
	}
	telemetryName := name(telemetry.ImportPath(), telemetry.packageName())

	factories := map[Kind][]string{}
	modules := map[Kind][][2]string{} // factory, "path version"
	var packages [][3]string          // kind, import path, factory
	for _, kind := range Kinds {
		for _, c := range m.Components(kind) {
			expr, ok := opts.Overrides[c.ModulePath()]
			if !ok {
				expr = name(c.ImportPath(), c.packageName()) + ".NewFactory()"
			}
			factories[kind] = append(factories[kind], expr)
			modules[kind] = append(modules[kind], [2]string{expr, c.ModulePath() + " " + c.Version()})
			packages = append(packages, [3]string{string(kind), c.ImportPath(), expr})
		}
	}

	var b bytes.Buffer
	source := opts.Source
	if source == "" {
		source = "an OCB manifest"
	}
	fmt.Fprintf(&b, "// Code generated by internal/debugger/registry/gen from %s. DO NOT EDIT.\n\n", source)
	fmt.Fprintf(&b, "package %s\n\n", opts.Package)
	b.WriteString("import (\n")
	b.WriteString("\t\"go.opentelemetry.io/collector/component\"\n")
	for _, kp := range kindPackages {
		fmt.Fprintf(&b, "\t%q\n", kp.pkg)
	}
	b.WriteString("\t\"go.opentelemetry.io/collector/otelcol\"\n\n")
	paths := make([]string, 0, len(imports))
	for p := range imports {
		paths = append(paths, p)
	}
	slices.Sort(paths)
	for _, p := range paths {
		if imports[p] == path.Base(p) {
			fmt.Fprintf(&b, "\t%q\n", p)
		} else {
			fmt.Fprintf(&b, "\t%s %q\n", imports[p], p)
		}
	}
	b.WriteString(")\n\n")

	b.WriteString("// Factories returns the unmodified upstream factories of the manifest's\n")
	b.WriteString("// components and, as OCB's registry records it, the module of each.\n")
	b.WriteString("func Factories() (otelcol.Factories, error) {\n")
	b.WriteString("\tvar err error\n")
	fmt.Fprintf(&b, "\tfactories := otelcol.Factories{Telemetry: %s.NewFactory()}\n\n", telemetryName)
	for _, kp := range kindPackages {
		fmt.Fprintf(&b, "\tif factories.%s, err = otelcol.MakeFactoryMap[%s.Factory](\n", kp.field, path.Base(kp.pkg))
		for _, f := range factories[kp.kind] {
			fmt.Fprintf(&b, "\t\t%s,\n", f)
		}
		b.WriteString("\t); err != nil {\n\t\treturn otelcol.Factories{}, err\n\t}\n")
		fmt.Fprintf(&b, "\tfactories.%sModules = modulesOf(factories.%s, map[component.Type]string{\n", strings.TrimSuffix(kp.field, "s"), kp.field)
		for _, mod := range modules[kp.kind] {
			fmt.Fprintf(&b, "\t\t%s.Type(): %q,\n", mod[0], mod[1])
		}
		b.WriteString("\t})\n")
	}
	b.WriteString("\treturn factories, nil\n}\n\n")

	b.WriteString("// componentTypes maps each component's Go package to its \"<kind>/<type>\"\n")
	b.WriteString("// names: its type and its deprecated type, if it has one.\n")
	b.WriteString("func componentTypes() map[string][]string {\n\ttypes := map[string][]string{}\n")
	b.WriteString("\tfor _, c := range []struct {\n\t\tpkg   string\n\t\tnames []string\n\t}{\n")
	for _, p := range packages {
		fmt.Fprintf(&b, "\t\t{%q, typeNames(%q, %s)},\n", p[1], p[0], p[2])
	}
	b.WriteString("\t} {\n\t\ttypes[c.pkg] = append(types[c.pkg], c.names...)\n\t}\n\treturn types\n}\n")

	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("manifest: generated registry does not parse: %w", err)
	}
	return out, nil
}

// OTTLVariants are the first releases of the OTTL variants in
// internal/debugger/compat/ottl (since<NNNN>), oldest first.
var OTTLVariants = []string{"0.160.0", "0.161.0", "0.162.0"}

// ottlCompat is the import path of the OTTL facade, whose variants are its
// subpackages.
const ottlCompat = "github.com/lineahq/linea/internal/debugger/compat/ottl"

// OTTLVariant returns the variant package for a Collector release: the
// newest variant at or before it, so a release newer than the support
// table gets the newest variants. Releases before the first variant are
// refused.
func OTTLVariant(version string) (string, error) {
	v := "v" + strings.TrimPrefix(version, "v")
	if !semver.IsValid(v) {
		return "", fmt.Errorf("manifest: %q is not a Collector release", version)
	}
	for i := len(OTTLVariants) - 1; i >= 0; i-- {
		if semver.Compare(v, "v"+OTTLVariants[i]) >= 0 {
			minor, _ := strconv.Atoi(strings.Split(OTTLVariants[i], ".")[1])
			return fmt.Sprintf("%s/since%04d", ottlCompat, minor), nil
		}
	}
	return "", fmt.Errorf("manifest: Collector %s is older than %s, the oldest release the debugger supports", strings.TrimPrefix(version, "v"), OTTLVariants[0])
}

// variantBindings are the facade's unexported bindings and the variant
// functions they bind.
var variantBindings = [][2]string{
	{"newResource", "Resource"}, {"newScope", "Scope"}, {"newSpan", "Span"}, {"newSpanEvent", "SpanEvent"},
	{"newLog", "Log"}, {"newMetric", "Metric"}, {"newDataPoint", "DataPoint"}, {"newExemplar", "Exemplar"},
}

// GenerateOTTLVariant writes internal/debugger/compat/ottl/variant.go for a
// Collector release: the facade's bindings to the release's variant.
func GenerateOTTLVariant(version, source string) ([]byte, error) {
	pkg, err := OTTLVariant(version)
	if err != nil {
		return nil, err
	}
	if source == "" {
		source = "an OCB manifest"
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by internal/debugger/registry/gen from %s. DO NOT EDIT.\n\n", source)
	b.WriteString("package ottlcompat\n\n")
	b.WriteString("import (\n\t\"github.com/open-telemetry/opentelemetry-collector-contrib/pkg/ottl\"\n\n")
	fmt.Fprintf(&b, "\tvariant %q\n)\n\n", pkg)
	fmt.Fprintf(&b, "// Variant is the first Collector release of the OTTL variant compiled for\n// Collector %s.\n", strings.TrimPrefix(version, "v"))
	b.WriteString("const Variant = variant.Since\n\n")
	b.WriteString("func functions[K any](m map[string]ottl.Factory[K]) map[string]ottl.Factory[K] {\n\treturn variant.Functions(m)\n}\n\n")
	b.WriteString("var (\n")
	for _, f := range variantBindings {
		fmt.Fprintf(&b, "\t%s = variant.%s\n", f[0], f[1])
	}
	b.WriteString(")\n")
	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("manifest: generated OTTL variant does not parse: %w", err)
	}
	return out, nil
}

// GenerateFeatureSet writes the Go source of internal/debugger/featureset for the
// manifest: a blank import of each optional feature's package (packages,
// by component module) whose component the manifest names.
func GenerateFeatureSet(m *Manifest, packages map[string]string, source string) ([]byte, error) {
	var imports []string
	for _, kind := range Kinds {
		for _, c := range m.Components(kind) {
			if pkg, ok := packages[c.ModulePath()]; ok && !slices.Contains(imports, pkg) {
				imports = append(imports, pkg)
			}
		}
	}
	slices.Sort(imports)
	if source == "" {
		source = "an OCB manifest"
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by internal/debugger/registry/gen from %s. DO NOT EDIT.\n\n", source)
	b.WriteString("// Package featureset compiles in the optional features of the manifest's\n")
	b.WriteString("// components: each imported package provides its feature to\n// package features.\n")
	b.WriteString("package featureset\n")
	if len(imports) > 0 {
		b.WriteString("\nimport (\n")
		for _, p := range imports {
			fmt.Fprintf(&b, "\t_ %q\n", p)
		}
		b.WriteString(")\n")
	}
	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("manifest: generated feature set does not parse: %w", err)
	}
	return out, nil
}

// ProviderImport is a package exporting DebuggerProvider.
type ProviderImport struct {
	// Package is its import path.
	Package string
}

// GenerateProviders writes the registry's providers.go: Providers lists
// each package's DebuggerProvider, in import path order. The built-in
// registry has none; a runtime build lists those its sources export.
func GenerateProviders(imports []ProviderImport, source string) ([]byte, error) {
	pkgs := make([]string, 0, len(imports))
	for _, p := range imports {
		if !slices.Contains(pkgs, p.Package) {
			pkgs = append(pkgs, p.Package)
		}
	}
	slices.Sort(pkgs)
	if source == "" {
		source = "an OCB manifest"
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by internal/debugger/registry/gen from %s. DO NOT EDIT.\n\n", source)
	b.WriteString("package registry\n\n")
	if len(pkgs) > 0 {
		b.WriteString("import (\n")
		for i, p := range pkgs {
			fmt.Fprintf(&b, "\tprovider%d %q\n", i, p)
		}
		b.WriteString(")\n\n")
	}
	b.WriteString("// Providers are the debugger providers of the component modules compiled\n")
	b.WriteString("// into this registry, in import path order.\n")
	b.WriteString("func Providers() []Provider {\n")
	if len(pkgs) == 0 {
		b.WriteString("\treturn nil\n}\n")
	} else {
		b.WriteString("\treturn []Provider{\n")
		for i, p := range pkgs {
			fmt.Fprintf(&b, "\t\t{Package: %q, New: provider%d.DebuggerProvider},\n", p, i)
		}
		b.WriteString("\t}\n}\n")
	}
	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("manifest: generated providers do not parse: %w", err)
	}
	return out, nil
}

// GenerateRelease writes the Go source of package release for the manifest:
// the Collector release line of the built-in runtime (CollectorVersion) and
// its component modules (Modules). It imports nothing, so a binary that links
// no component still knows the release its built-in runtime is on.
func GenerateRelease(m *Manifest, source string) ([]byte, error) {
	if m.Dist.OtelcolVersion == "" {
		return nil, fmt.Errorf("manifest: dist.otelcol_version is required")
	}
	if source == "" {
		source = "an OCB manifest"
	}
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated by internal/debugger/registry/gen from %s. DO NOT EDIT.\n\n", source)
	b.WriteString("package release\n\n")
	b.WriteString("// CollectorVersion is the Collector release line of the built-in runtime,\n// dist.otelcol_version in the manifest.\n")
	fmt.Fprintf(&b, "const CollectorVersion = %q\n\n", m.Dist.OtelcolVersion)
	b.WriteString("// Modules lists the Go modules of every component of the built-in runtime,\n")
	b.WriteString("// in the same \"path version\" form OCB uses, in manifest order.\n")
	b.WriteString("var Modules = []string{\n")
	for _, mod := range m.Modules() {
		fmt.Fprintf(&b, "\t%q,\n", mod)
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}
